-- مصفوفة تجاور لرسم بياني موجه: 1 تعني وجود حافة
CREATE TABLE graph(src TEXT, dst TEXT, PRIMARY KEY(src, dst));
INSERT INTO graph VALUES ('A','B'), ('A','C'), ('B','C'), ('C','A');

-- هل توجد حافة من A إلى C؟
SELECT EXISTS(SELECT 1 FROM graph WHERE src='A' AND dst='C');

