DELETE FROM emp WHERE id = 2;
SELECT id, name, salary FROM emp;

-- جدول مرتب تصاعديًا
CREATE TABLE arr (idx INTEGER PRIMARY KEY, val INTEGER);
INSERT INTO arr VALUES (1, 10), (2, 20), (3, 30), (4, 40), (5, 50);
-- البحث الثنائي عن 30: نبدأ من المنتصف ونقارن
SELECT val FROM arr WHERE idx = (SELECT COUNT(*)/2 + 1 FROM arr) AND val = 30;

WITH RECURSIVE fib(a, b, n) AS (
  SELECT 0, 1, 1
  UNION ALL
  SELECT b, a+b, n+1 FROM fib WHERE n < 10
)
SELECT a FROM fib;

WITH RECURSIVE dates(d) AS (
  SELECT '2024-01-01'
  UNION ALL
  SELECT date(d, '+1 day') FROM dates WHERE d < '2024-01-05'
)
SELECT d FROM dates;

