-- إعداد الجدول المؤقت للقيم
CREATE TABLE gcd_state (a INTEGER, b INTEGER);
INSERT INTO gcd_state VALUES (48, 18);
-- تكرار الطرح: نستبدل (a,b) بـ (b, a%b) حتى يصبح b صفرًا
WITH RECURSIVE gcd_iter(a, b) AS (
  SELECT a, b FROM gcd_state
  UNION ALL
  SELECT b, a % b FROM gcd_iter WHERE b != 0
)
SELECT a FROM gcd_iter WHERE b = 0;

CREATE TABLE emp_dept (emp_id INTEGER PRIMARY KEY, emp_name TEXT, dept_id INTEGER, dept_name TEXT);
INSERT INTO emp_dept VALUES (1, 'Ali', 10, 'CS'), (2, 'Sara', 20, 'IS');
CREATE TABLE emp (emp_id INTEGER PRIMARY KEY, emp_name TEXT, dept_id INTEGER);
CREATE TABLE dept (dept_id INTEGER PRIMARY KEY, dept_name TEXT);
INSERT INTO emp SELECT emp_id, emp_name, dept_id FROM emp_dept;
INSERT INTO dept SELECT DISTINCT dept_id, dept_name FROM emp_dept;
SELECT e.emp_name, d.dept_name FROM emp e JOIN dept d ON e.dept_id = d.dept_id ORDER BY e.emp_id;

-- لماذا جدولان؟ لفصل العقد عن الحواف
CREATE TABLE vertices(id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE edges(src INTEGER, dst INTEGER);
INSERT INTO vertices VALUES (1,'A'),(2,'B'),(3,'C'),(4,'D');
INSERT INTO edges VALUES (1,2),(1,3),(2,4),(3,4);
-- جيران العقدة 1
SELECT v.name FROM edges e JOIN vertices v ON e.dst=v.id WHERE e.src=1 ORDER BY v.name;

-- لماذا المفتاح فريد؟ لضمان عدم التكرار وسرعة البحث
CREATE TABLE dict(key TEXT PRIMARY KEY, val INTEGER);
INSERT INTO dict VALUES ('apple',3),('banana',5),('cherry',2);
-- البحث عن قيمة مفتاح معين
SELECT val FROM dict WHERE key='banana';
-- تحديث قيمة مفتاح موجود
UPDATE dict SET val=7 WHERE key='banana';
SELECT val FROM dict WHERE key='banana';

-- لماذا الترتيب التصاعدي؟ لأن الكومة الصغرى تضع الأصغر في الأعلى
CREATE TABLE heap(val INTEGER);
INSERT INTO heap VALUES (5),(3),(8),(1),(9);
-- استخراج الأصغر (محاكاة extract-min)
SELECT val FROM heap ORDER BY val ASC LIMIT 1;
DELETE FROM heap WHERE val=1;
SELECT val FROM heap ORDER BY val ASC LIMIT 1;

-- إنشاء جدول الأرقام وملؤه
CREATE TABLE nums (val INTEGER);
INSERT INTO nums VALUES (5), (12), (7), (3), (9);
-- البحث الخطي عن القيمة 7: نستعلم عن الصف الأول الذي يحقق الشرط
SELECT val FROM nums WHERE val = 7 LIMIT 1;

CREATE TABLE raw_data (student TEXT, courses TEXT);
