CREATE TABLE sales(month TEXT, amount INT);
INSERT INTO sales VALUES ('Jan',100),('Feb',150),('Mar',200);
SELECT
  SUM(CASE WHEN month='Jan' THEN amount END) AS Jan,
  SUM(CASE WHEN month='Feb' THEN amount END) AS Feb,
  SUM(CASE WHEN month='Mar' THEN amount END) AS Mar
FROM sales;

-- طابور أولوية: عناصر بأولويات مختلفة
CREATE TABLE pq(item TEXT, priority INTEGER);
INSERT INTO pq VALUES ('low', 3), ('high', 1), ('medium', 2);

-- استخراج العنصر الأعلى أولوية (أصغر رقم)
SELECT item FROM pq ORDER BY priority LIMIT 1;

-- لماذا الترتيب التصاعدي؟ لأن الطابور يخرج من الأمام
CREATE TABLE queue(item TEXT, seq INTEGER);
INSERT INTO queue VALUES ('first',1),('second',2),('third',3);
-- محاكاة dequeue: خذ الأمام ثم احذفه
SELECT item FROM queue ORDER BY seq ASC LIMIT 1;
DELETE FROM queue WHERE seq=1;
SELECT item FROM queue ORDER BY seq ASC LIMIT 1;

