-- لماذا جدولان؟ لفصل العقد عن الروابط
CREATE TABLE nodes(id INTEGER PRIMARY KEY, val TEXT);
CREATE TABLE links(prev_id INTEGER, next_id INTEGER);
INSERT INTO nodes VALUES (1,'A'),(2,'B'),(3,'C');
INSERT INTO links VALUES (1,2),(2,3);
-- اجتياز القائمة: ابدأ من الرأس (1) واتبع الروابط
WITH RECURSIVE traverse(id, val) AS (
  SELECT id, val FROM nodes WHERE id=1
  UNION ALL
  SELECT n.id, n.val FROM traverse t JOIN links l ON t.id=l.prev_id JOIN nodes n ON l.next_id=n.id
)
SELECT val FROM traverse;

-- لماذا الترتيب التنازلي؟ لأن المكدس يخرج من الأعلى
CREATE TABLE stack(item TEXT, seq INTEGER);
INSERT INTO stack VALUES ('first',1),('second',2),('third',3);
-- محاكاة pop: خذ الأعلى ثم احذفه
SELECT item FROM stack ORDER BY seq DESC LIMIT 1;
DELETE FROM stack WHERE seq=3;
SELECT item FROM stack ORDER BY seq DESC LIMIT 1;

